-- Generated by pnpm pages:sync from lib/navigation/registry.ts.
-- Review and deploy through the regular migration and release gates.
-- Existing visibility choices and user overrides are preserved.

begin;

set local lock_timeout = '5s';
set local statement_timeout = '30s';

on conflict (key) do nothing;

on conflict (key) do update set
  path = excluded.path,
  name = excluded.name,
  description = excluded.description,
  section = excluded.section,
  permission_key = excluded.permission_key,
  parent_key = excluded.parent_key,
  sort_order = excluded.sort_order,
  is_navigation = excluded.is_navigation;

-- New page permissions are inherited only by the two administrative roles.
-- Other role defaults and all individual overrides remain unchanged.
select role_key, permission_key
from (values ('master'), ('admin')) roles(role_key)
cross join (values ('admin.access'), ('crm.dashboard.view'), ('crm.partnerships.view'), ('crm.ranking.view'), ('crm.settings.manage'), ('crm.settings.view'), ('crm.simulators.view'), ('crm.stages.view'), ('pages.manage'), ('users.view')) permissions(permission_key)
on conflict (role_key, permission_key) do nothing;

notify pgrst, 'reload schema';

commit;
